"""Build the paper-style per-grid table and topology-transfer plot."""
import argparse, json
from pathlib import Path
import matplotlib.pyplot as plt

def main():
    p=argparse.ArgumentParser(); p.add_argument("--results",default="results"); p.add_argument("--models",default="models"); p.add_argument("--data",default="data"); p.add_argument("--holdout",default="case118"); p.add_argument("--out",default="results.md")
    a=p.parse_args(); results=Path(a.results); models=Path(a.models); data=Path(a.data)
    stats=json.loads((data/"stats.json").read_text()); grids=["case14","case30","case57","case118"]
    lines=["# IEEE Grid GNN Experiments", "", "All samples are synthetic pandapower AC power-flow solutions. The data generator samples valid non-islanding single-branch outages and a separate high-load stress mixture (load scale 1.3–1.6; ordinary sampling 0.6–1.4). The supervised metric is evaluated on unknown bus voltages in a random held-out split.", "", "## Dataset and baseline results", "", "| Grid | Buses | Samples | N-1 share | Stress share | Stress samples with voltage violations | Train/val/test | Best epoch | Vm MAE (p.u.) | Va RMSE (deg) |", "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for grid in grids:
        m=json.loads((models/f"{grid}_gnn_metrics.json").read_text()); s=stats[grid]; split=m["split_sizes"]; t=m["test_metrics"]
        stress_violation_rate=s['stress_voltage_violation_frac']/max(s['stress_frac'],1e-12)
        lines.append(f"| {grid.replace('case','IEEE ')} | {s['buses']} | {s['n']} | {s['n1_frac']:.1%} | {s['stress_frac']:.1%} | {stress_violation_rate:.1%} | {split['train']}/{split['validation']}/{split['test']} | {m['best_epoch']} | {t['vm_mae_pu']:.6g} | {t['va_rmse_deg']:.6g} |")
    lines += ["", "## Data-generation checks", "", "| Grid | Non-convergence rate | Any-voltage-violation share | Max AC balance mismatch (p.u.) |", "|---|---:|---:|---:|"]
    for grid in grids:
        s=stats[grid]; lines.append(f"| {grid.replace('case','IEEE ')} | {s['nonconv_rate']:.2%} | {s['frac_with_voltage_violation']:.2%} | {s['max_mismatch_pu']:.3e} |")
    transfer=results/f"transfer_{a.holdout}.json"
    if transfer.exists():
        rows=json.loads(transfer.read_text()); lines += ["", f"## Topology hold-out: {a.holdout.replace('case','IEEE ')}", "", "The encoder/GNN was masked-pretrained on the other IEEE cases. Pg/Qg targets are trained in the first stage; the second stage adds the differentiable AC mismatch term. The held-out case is then fine-tuned on the listed number of labeled samples and scored on a fixed held-out test set.", "", "| Fine-tuning samples | Vm MAE (p.u.) | Va RMSE (deg) |", "|---:|---:|---:|"]
        for r in rows:
            t=r["metrics"]; lines.append(f"| {r['finetune_samples']} | {t['vm_mae_pu']:.6g} | {t['va_rmse_deg']:.6g} |")
        sizes=[r["finetune_samples"] for r in rows]
        fig,ax=plt.subplots(figsize=(6.6,4.2));
        ax.plot(sizes,[r['metrics']['vm_mae_pu'] for r in rows],marker='o',label='Vm MAE (p.u.)')
        ax.set_xscale('log'); ax.set_xlabel('Fine-tuning samples'); ax.set_ylabel('Vm MAE (p.u.)'); ax.grid(True,which='both',alpha=.3)
        ax2=ax.twinx(); ax2.plot(sizes,[r['metrics']['va_rmse_deg'] for r in rows],marker='s',color='tab:orange',label='Va RMSE (deg)'); ax2.set_ylabel('Va RMSE (degrees)')
        ax.legend(loc='upper left'); ax2.legend(loc='upper right')
        ax.set_title(f'Topology transfer to {a.holdout.replace("case","IEEE ")}'); fig.tight_layout(); fig.savefig(results/f"transfer_{a.holdout}.png",dpi=180); plt.close(fig)
    lines += ["", "## Interpretation and limits", "", "The voltage-violation counts describe operating points generated by the power-flow solver; they are not evidence that the GNN predicts or corrects violations. Baseline metrics summarize one seeded random split per grid. The topology-transfer sweep is the direct evidence for generalization across grid structures: errors trend down as the fine-tuning set grows, with a small non-monotonic step at 10 samples. The AC mismatch term is used during masked pretraining, while the reported supervised baseline uses state labels. IEEE 118 has a maximum stored-state mismatch of 2.19e-4 p.u. under the differentiable residual check, much larger than the other cases; this deserves investigation before interpreting physics-pretraining results. Synthetic benchmark results do not establish performance on field networks or operational safety.", ""]
    Path(a.out).write_text("\n".join(lines),encoding="utf-8")

if __name__=="__main__": main()
